package com.lqq.supportflow.action.api;
import com.lqq.supportflow.action.application.ManageApprovalService; import com.lqq.supportflow.action.domain.*; import com.lqq.supportflow.shared.AuthenticatedPrincipal; import jakarta.validation.Valid; import java.util.List; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/approvals") public class AdminApprovalController { private final ManageApprovalService service; public AdminApprovalController(ManageApprovalService service){this.service=service;} @GetMapping List<Approval> list(@AuthenticationPrincipal AuthenticatedPrincipal principal){return service.list(principal.tenantId());} @PostMapping ResponseEntity<Approval> create(@AuthenticationPrincipal AuthenticatedPrincipal principal,@Valid @RequestBody CreateApprovalRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(principal.tenantId(),null,request.actionType(),request.actionSummary(),principal.membershipId()));} @PostMapping("/{approvalId}/decision") Approval decide(@AuthenticationPrincipal AuthenticatedPrincipal principal,@PathVariable Long approvalId,@RequestHeader("Idempotency-Key") String idempotencyKey,@Valid @RequestBody DecisionRequest request){return service.decide(principal.tenantId(),approvalId,principal.membershipId(),request.decision(),idempotencyKey);}}
